{"implementation":"import math

def solve(case):
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']

    n = len(sentence_vectors)
    if n == 0:
        return {'ranking': [], 'scores': []}

    dim = len(query_vector)
    context = [sum(sv[i] for sv in sentence_vectors) / n for i in range(dim)]

    q = [(1 - context_weight) * qv + context_weight * cv for qv, cv in zip(query_vector, context)]

    def norm(v):
        return math.sqrt(sum(x*x for x in v))

    def dot(a, b):
        return sum(ai*bi for ai, bi in zip(a, b))

    q_norm = norm(q)
    similarities = []
    for sv in sentence_vectors:
        if q_norm == 0:
            sim = 0.0
        else:
            sim = dot(q, sv) / (q_norm * norm(sv))
        similarities.append(sim)

    indices = sorted(range(len(similarities)), key=lambda i: (-similarities[i], i))
    ranks = [0] * len(similarities)
    for rank, idx in enumerate(indices, start=1):
        ranks[idx] = rank

    return {'ranking': ranks, 'scores': similarities}"}
